        split.append((op, rest))
    alt = _Alternative()
    for op, rest in split:
        alt.add(_comparators(op, _parse_partial(rest)))
    return alt


class Range:
    def __init__(self, text: str, alternatives, exact: bool):
        self.text = text
        self._alternatives = alternatives
        self._exact = exact

    def test(self, version: Version) -> bool:
        """True when `version` satisfies the range."""
        return any(a.test(version) for a in self._alternatives)

    def is_exact(self) -> bool:
        """True for a range that names one version (docs/ranges.md, section 10)."""
        return self._exact

    def __str__(self):
        return self.text


def parse_range(text: str) -> Range:
    if not isinstance(text, str):
        raise RangeError("bad-range", f"a range is a string, not {type(text).__name__}")
    if not text.strip(" \t"):
        raise RangeError("bad-range", "empty range")
    texts = text.split("||")
    if any(not t.strip(" \t") for t in texts):
        raise RangeError("bad-range", "empty alternative")
    alternatives = [_read_alternative(t) for t in texts]
    exact = False
    if len(texts) == 1:
        tokens = SPACES_RE.split(texts[0].strip(" \t"))
        if len(tokens) == 1:
            tok = tokens[0]
            body = tok[1:] if tok.startswith("=") else tok
            exact = bool(re.fullmatch(r"\d.*", body)) and _is_full(body)
    return Range(text, alternatives, exact)


def _is_full(body: str) -> bool:
    try:
        Version.parse(body)
    except VersionError:
        return False
    return True
