"""Version ranges, as written in manifests and in index dependencies (docs/ranges.md)."""

import re

from pinset.errors import RangeError, VersionError
from pinset.version import BUILD_RE, PRERELEASE_RE, Version

OPERATORS = ("<=", ">=", "<", ">", "=", "^", "~")
WILDCARDS = ("x", "X", "*")
NUMBER_RE = re.compile(r"0|[1-9][0-9]*")
SPACES_RE = re.compile(r"[ \t]+")
START_CHARS = "0123456789xX*"

ANY = ()  # an alternative without comparators accepts every release


class _Never:
    pass


def _ver(major, minor, patch, pre=()):
    return Version(major, minor, patch, pre)


def _floor(major, minor, patch):
    """Lower than every version of the release (docs/ranges.md, section 4: `<X-0`)."""
    return _ver(major, minor, patch, ("0",))


class _Partial:
    def __init__(self, nums, prerelease):
        self.nums = nums  # list of ints, 0 to 3 long (wildcards stop the list)
        self.prerelease = prerelease

    @property
    def full(self):
        return len(self.nums) == 3

    def padded(self):
        return tuple(self.nums) + (0,) * (3 - len(self.nums))


def _parse_partial(text: str) -> _Partial:
    main, plus, build = text.partition("+")
    main, dash, pre = main.partition("-")
    parts = main.split(".")
    if not 1 <= len(parts) <= 3:
        raise RangeError("bad-version", f"bad version {text!r}")
    nums = []
    wild = False
    for part in parts:
        if part in WILDCARDS:
            wild = True
        elif NUMBER_RE.fullmatch(part):
            if wild:
                raise RangeError("bad-version", f"a number after a wildcard in {text!r}")
            nums.append(int(part))
        else:
            raise RangeError("bad-version", f"bad part {part!r} in {text!r}")
    if dash and not PRERELEASE_RE.fullmatch(pre):
        raise RangeError("bad-version", f"bad prerelease in {text!r}")
    if plus and not BUILD_RE.fullmatch(build):
        raise RangeError("bad-version", f"bad build in {text!r}")
    if (dash or plus) and (len(parts) != 3 or len(nums) != 3):
        raise RangeError("bad-version", f"prerelease or build without a full version in {text!r}")
    return _Partial(nums, tuple(pre.split(".")) if dash else ())


def _next_block_end(nums):
    """Exclusive upper bound `<X-0` for the block a partial of 1 or 2 numbers names."""
    if len(nums) == 1:
        return _floor(nums[0] + 1, 0, 0)
    return _floor(nums[0], nums[1] + 1, 0)


def _comparators(op: str, pt: _Partial):
    """(list of (kind, Version), carrier release or None), or _Never for no version."""
    nums = pt.nums
    n = len(nums)
    if pt.full:
        v = _ver(*nums, pt.prerelease)
        carrier = tuple(nums) if pt.prerelease else None
        if op in ("", "="):
            return [("ge", v), ("le", v)], carrier
        if op == ">=":
            return [("ge", v)], carrier
        if op == ">":
            return [("gt", v)], carrier
        if op == "<=":
            return [("le", v)], carrier
        if op == "<":
            return [("lt", v)], carrier
        low = _ver(*nums, pt.prerelease)
        if op == "~":
            return [("ge", low), ("lt", _floor(nums[0], nums[1] + 1, 0))], carrier
        # caret
        if nums[0] > 0:
            up = _floor(nums[0] + 1, 0, 0)
        elif nums[1] > 0:
            up = _floor(0, nums[1] + 1, 0)
        else:
            up = _floor(0, 0, nums[2] + 1)
        return [("ge", low), ("lt", up)], carrier
    # partial with wildcards
    if n == 0:
        if op in ("<", ">"):
            return _Never, None
        return [], None
    low = _ver(*pt.padded())
    block_end = _next_block_end(nums)
    if op in ("", "="):
        return [("ge", low), ("lt", block_end)], None
    if op == ">=":
        return [("ge", low)], None
    if op == ">":
        return [("ge", _ver(*block_end.release))], None
    if op == "<":
        return [("lt", _floor(*low.release))], None
    if op == "<=":
        return [("lt", block_end)], None
    if op == "~":
        return [("ge", low), ("lt", block_end)], None
    # caret
    if nums[0] > 0 or n == 1:
        up = _floor(nums[0] + 1, 0, 0)
    elif nums[1] > 0:
        up = _floor(0, nums[1] + 1, 0)
    elif n == 2:
        up = _floor(0, 1, 0)
    else:
        up = _floor(0, 0, nums[2] + 1)
    return [("ge", low), ("lt", up)], None


class _Alternative:
    def __init__(self):
        self.comparators = []  # (kind, Version)
        self.carriers = set()  # releases named with a prerelease
        self.never = False

    def add(self, result):
        comps, carrier = result
        if comps is _Never:
            self.never = True
            return
        self.comparators.extend(comps)
        if carrier is not None:
            self.carriers.add(carrier)

    def test(self, v: Version) -> bool:
        if self.never:
            return False
        for kind, bound in self.comparators:
            if kind == "ge":
                ok = v >= bound
            elif kind == "gt":
                ok = v > bound
            elif kind == "le":
                ok = v <= bound
            else:
                ok = v < bound
            if not ok:
                return False
        if v.is_prerelease() and v.release not in self.carriers:
            return False
        return True


