        if lo.prerelease:
            alt.carriers.add(tuple(lo.nums))
    if hi.nums:
        if hi.full:
            alt.comparators.append(("le", _ver(*hi.nums, hi.prerelease)))
            if hi.prerelease:
                alt.carriers.add(tuple(hi.nums))
        else:
            alt.comparators.append(("lt", _next_block_end(hi.nums)))
    return alt


def _read_alternative(text: str) -> _Alternative:
    tokens = SPACES_RE.split(text.strip(" \t"))
    if "-" in tokens:
        return _read_hyphen(tokens)
    split = []
    for tok in tokens:
        op = next((o for o in OPERATORS if tok.startswith(o)), "")
        rest = tok[len(op):]
        if not rest or rest[0] not in START_CHARS:
            raise RangeError("bad-range", f"cannot read {tok!r}")
        split.append((op, rest))
    alt = _Alternative()
    for op, rest in split:
        alt.add(_comparators(op, _parse_partial(rest)))
    return alt


class Range:
    def __init__(self, text: str, alternatives, exact: bool):
        self.text = text
        self._alternatives = alternatives
        self._exact = exact

    def test(self, version: Version) -> bool:
        """True when `version` satisfies the range."""
        return any(a.test(version) for a in self._alternatives)

    def is_exact(self) -> bool:
        """True for a range that names one version (docs/ranges.md, section 10)."""
        return self._exact

    def __str__(self):
        return self.text


def parse_range(text: str) -> Range:
    if not isinstance(text, str):
        raise RangeError("bad-range", f"a range is a string, not {type(text).__name__}")
    if not text.strip(" \t"):
